#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

vector<int> berlekampMassey(const vector<int>& s) {
    vector<int> C(1, 1), B(1, 1);
    int L = 0, shift = 1;
    int b = 1;

    for (int pos = 0; pos < (int)s.size(); ++pos) {
        long long discrepancy = 0;
        for (int i = 0; i <= L; ++i) {
            discrepancy += 1LL * C[i] * s[pos - i];
            discrepancy %= MOD;
        }

        if (discrepancy == 0) {
            ++shift;
            continue;
        }

        vector<int> oldC = C;
        int coefficient = (int)(discrepancy * modPow(b, MOD - 2) % MOD);

        if ((int)C.size() < (int)B.size() + shift)
            C.resize(B.size() + shift, 0);

        for (int i = 0; i < (int)B.size(); ++i) {
            C[i + shift] =
                (C[i + shift] - 1LL * coefficient * B[i]) % MOD;
            if (C[i + shift] < 0) C[i + shift] += MOD;
        }

        if (2 * L <= pos) {
            L = pos + 1 - L;
            B = move(oldC);
            b = (int)discrepancy;
            shift = 1;
        } else {
            ++shift;
        }
    }

    vector<int> recurrence(L);
    for (int i = 1; i <= L; ++i) {
        recurrence[i - 1] = C[i] == 0 ? 0 : MOD - C[i];
    }
    return recurrence;
}

int linearRecurrenceTerm(const vector<int>& initial,
                         const vector<int>& recurrence,
                         long long index) {
    int L = recurrence.size();
    if (index < (long long)initial.size()) return initial[index];

    auto combine = [&](const vector<int>& a,
                       const vector<int>& b) -> vector<int> {
        vector<int> product(2 * L - 1, 0);

        for (int i = 0; i < L; ++i) {
            if (a[i] == 0) continue;
            for (int j = 0; j < L; ++j) {
                if (b[j] == 0) continue;
                product[i + j] =
                    (product[i + j] + 1LL * a[i] * b[j]) % MOD;
            }
        }

        for (int degree = 2 * L - 2; degree >= L; --degree) {
            int value = product[degree];
            if (value == 0) continue;

            for (int j = 1; j <= L; ++j) {
                product[degree - j] =
                    (product[degree - j] +
                     1LL * value * recurrence[j - 1]) % MOD;
            }
        }

        product.resize(L);
        return product;
    };

    vector<int> result(L, 0), power(L, 0);
    result[0] = 1;

    if (L == 1) power[0] = recurrence[0];
    else power[1] = 1;

    while (index > 0) {
        if (index & 1) result = combine(result, power);
        index >>= 1;
        if (index > 0) power = combine(power, power);
    }

    long long answer = 0;
    for (int i = 0; i < L; ++i) {
        answer += 1LL * result[i] * initial[i];
        answer %= MOD;
    }
    return (int)answer;
}

struct Edge {
    int from, to;
    char ch;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<string> words(n);
    for (string& word : words) cin >> word;

    int states = 1;
    vector<Edge> automatonEdges;

    for (const string& word : words) {
        int length = word.size();
        vector<int> middle(max(0, length - 1));

        for (int& state : middle) state = states++;

        for (int i = 0; i < length; ++i) {
            int from = (i == 0 ? 0 : middle[i - 1]);
            int to = (i == length - 1 ? 0 : middle[i]);
            automatonEdges.push_back({from, to, word[i]});
        }
    }

    int productStates = states * states;
    auto productId = [states](int a, int b) {
        return a * states + b;
    };

    vector<pair<int, int>> productEdges;
    for (const Edge& first : automatonEdges) {
        for (const Edge& second : automatonEdges) {
            if (first.ch == second.ch) {
                productEdges.push_back({
                    productId(first.from, second.from),
                    productId(first.to, second.to)
                });
            }
        }
    }

    vector<vector<int>> graph(productStates), reverseGraph(productStates);
    for (auto [from, to] : productEdges) {
        graph[from].push_back(to);
        reverseGraph[to].push_back(from);
    }

    int start = productId(0, 0);

    auto reachableFrom = [&](const vector<vector<int>>& g) {
        vector<char> visited(productStates, false);
        queue<int> q;
        visited[start] = true;
        q.push(start);

        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int to : g[v]) {
                if (!visited[to]) {
                    visited[to] = true;
                    q.push(to);
                }
            }
        }
        return visited;
    };

    vector<char> reachable = reachableFrom(graph);
    vector<char> canReachStart = reachableFrom(reverseGraph);

    vector<int> newId(productStates, -1);
    int usefulStates = 0;
    for (int i = 0; i < productStates; ++i) {
        if (reachable[i] && canReachStart[i])
            newId[i] = usefulStates++;
    }

    vector<pair<int, int>> usefulEdges;
    usefulEdges.reserve(productEdges.size());
    for (auto [from, to] : productEdges) {
        if (newId[from] != -1 && newId[to] != -1)
            usefulEdges.push_back({newId[from], newId[to]});
    }

    int newStart = newId[start];
    vector<int> values(usefulStates, 0), nextValues(usefulStates, 0);
    values[newStart] = 1;

    vector<int> sequence;
    sequence.reserve(2 * usefulStates);

    for (int step = 0; step < 2 * usefulStates; ++step) {
        sequence.push_back(values[newStart]);
        fill(nextValues.begin(), nextValues.end(), 0);

        for (auto [from, to] : usefulEdges) {
            int value = nextValues[to] + values[from];
            if (value >= MOD) value -= MOD;
            nextValues[to] = value;
        }
        values.swap(nextValues);
    }

    if (m < (long long)sequence.size()) {
        cout << sequence[m] << '\n';
        return 0;
    }

    vector<int> recurrence = berlekampMassey(sequence);
    vector<int> initial(recurrence.size());
    for (int i = 0; i < (int)recurrence.size(); ++i)
        initial[i] = sequence[i];

    cout << linearRecurrenceTerm(initial, recurrence, m) << '\n';
    return 0;
}

