int linearRecurrenceNth(const vector<int>& initial,
                        const vector<int>& recurrence,
                        long long n) {
    if (n < (long long)initial.size()) return initial[n];

    int k = recurrence.size();
    if (k == 0) return 0;

    auto combine = [&](const vector<int>& a, const vector<int>& b) {
        vector<int> temp(2 * k - 1, 0);

        for (int i = 0; i < k; ++i) {
            if (a[i] == 0) continue;
            for (int j = 0; j < k; ++j) {
                if (b[j] == 0) continue;
                temp[i + j] = (temp[i + j] +
                               1LL * a[i] * b[j]) % MOD;
            }
        }

        for (int degree = 2 * k - 2; degree >= k; --degree) {
            int value = temp[degree];
            if (value == 0) continue;

            for (int j = 0; j < k; ++j) {
                int target = degree - 1 - j;
                temp[target] = (temp[target] +
                                1LL * value * recurrence[j]) % MOD;
            }
        }

        temp.resize(k);
        return temp;
    };

    vector<int> result(k, 0), base(k, 0);
    result[0] = 1;

    if (k == 1)
        base[0] = recurrence[0];
    else
        base[1] = 1;

    while (n > 0) {
        if (n & 1) result = combine(result, base);
        n >>= 1;
        if (n) base = combine(base, base);
    }

    long long answer = 0;
    for (int i = 0; i < k; ++i) {
        answer += 1LL * result[i] * initial[i];
        answer %= MOD;
    }
    return (int)answer;
}

struct TrieNode {
    array<int, 26> child;
    bool terminal = false;

    TrieNode() {
        child.fill(-1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<TrieNode> trie(1);

    for (int i = 0; i < n; ++i) {
        string word;
        cin >> word;

        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (trie[node].child[c] == -1) {
                trie[node].child[c] = trie.size();
                trie.emplace_back();
            }
            node = trie[node].child[c];
        }
        trie[node].terminal = true;
    }

    vector<int> automatonId(trie.size(), -1);
    vector<int> trieNodeOfState;

    automatonId[0] = 0;
    trieNodeOfState.push_back(0);

    for (int node = 1; node < (int)trie.size(); ++node) {
        bool hasChild = false;
        for (int c = 0; c < 26; ++c) {
            if (trie[node].child[c] != -1) {
                hasChild = true;
                break;
            }
        }
        if (hasChild) {
            automatonId[node] = trieNodeOfState.size();
            trieNodeOfState.push_back(node);
        }
    }

    int states = trieNodeOfState.size();
    vector<array<vector<int>, 26>> next(states);

    for (int state = 0; state < states; ++state) {
        int node = trieNodeOfState[state];

        for (int c = 0; c < 26; ++c) {
            int child = trie[node].child[c];
            if (child == -1) continue;

            if (trie[child].terminal)
                next[state][c].push_back(0);

            if (automatonId[child] != -1)
                next[state][c].push_back(automatonId[child]);
        }
    }

    int totalPairs = states * states;
    vector<int> compressed(totalPairs, -1);
    vector<int> fullState;
    vector<vector<pair<int, int>>> edges;

    compressed[0] = 0;
    fullState.push_back(0);
    edges.emplace_back();

    vector<int> count(totalPairs, 0);
    vector<int> touched;

    for (int head = 0; head < (int)fullState.size(); ++head) {
        int full = fullState[head];
        int left = full / states;
        int right = full % states;
        touched.clear();

        for (int c = 0; c < 26; ++c) {
            for (int toLeft : next[left][c]) {
                for (int toRight : next[right][c]) {
                    int destination = toLeft * states + toRight;
                    if (count[destination] == 0)
                        touched.push_back(destination);
                    ++count[destination];
                }
            }
        }

        for (int destination : touched) {
            if (compressed[destination] == -1) {
                compressed[destination] = fullState.size();
                fullState.push_back(destination);
                edges.emplace_back();
            }
            edges[head].push_back({compressed[destination],
                                   count[destination]});
            count[destination] = 0;
        }
    }

    int productStates = fullState.size();
    int termsNeeded = 2 * productStates + 5;

    vector<int> sequence;
    sequence.reserve(termsNeeded);

    vector<int> dp(productStates, 0), nextDp(productStates, 0);
    dp[0] = 1;

    for (int length = 0; length < termsNeeded; ++length) {
        sequence.push_back(dp[0]);
        fill(nextDp.begin(), nextDp.end(), 0);

        for (int from = 0; from < productStates; ++from) {
            if (dp[from] == 0) continue;

            for (auto [to, weight] : edges[from]) {
                nextDp[to] = (nextDp[to] +
                              1LL * dp[from] * weight) % MOD;
            }
        }
        dp.swap(nextDp);
    }

    if (m < (long long)sequence.size()) {
        cout << sequence[m] << '\n';
        return 0;
    }

    vector<int> recurrence = berlekampMassey(sequence);
    vector<int> initial(sequence.begin(),
                        sequence.begin() + recurrence.size());

    cout << linearRecurrenceNth(initial, recurrence, m) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

long long mod_pow(long long a, long long e) {
