vector<int> berlekamp_massey(const vector<int>& s) {
    vector<int> C(1, 1), B(1, 1);
    int L = 0, shift = 1;
    int last_discrepancy = 1;

    for (int n = 0; n < (int)s.size(); ++n) {
        long long discrepancy = s[n];
        for (int i = 1; i <= L; ++i) {
            discrepancy += 1LL * C[i] * s[n - i];
        }
        discrepancy %= MOD;

        if (discrepancy == 0) {
            ++shift;
            continue;
        }

        vector<int> oldC = C;
        long long factor = discrepancy * mod_pow(last_discrepancy, MOD - 2) % MOD;

        if ((int)C.size() < (int)B.size() + shift)
            C.resize(B.size() + shift, 0);

        for (int i = 0; i < (int)B.size(); ++i) {
            C[i + shift] = (C[i + shift] - factor * B[i]) % MOD;
            if (C[i + shift] < 0) C[i + shift] += MOD;
        }

        if (2 * L <= n) {
            L = n + 1 - L;
            B = move(oldC);
            last_discrepancy = discrepancy;
            shift = 1;
        } else {
            ++shift;
        }
    }

    C.resize(L + 1);
    vector<int> recurrence(L);
    for (int i = 1; i <= L; ++i) {
        recurrence[i - 1] = C[i] == 0 ? 0 : MOD - C[i];
    }
    return recurrence;
}

vector<int> combine(const vector<int>& a, const vector<int>& b,
                    const vector<int>& recurrence) {
    int k = recurrence.size();
    vector<long long> product(2 * k - 1, 0);

    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            product[i + j] += 1LL * a[i] * b[j] % MOD;
            if (product[i + j] >= MOD) product[i + j] -= MOD;
        }
    }

    for (int degree = 2 * k - 2; degree >= k; --degree) {
        long long value = product[degree];
        if (value == 0) continue;
        for (int j = 1; j <= k; ++j) {
            product[degree - j] += value * recurrence[j - 1] % MOD;
            if (product[degree - j] >= MOD) product[degree - j] -= MOD;
        }
    }

    vector<int> result(k);
    for (int i = 0; i < k; ++i) result[i] = product[i] % MOD;
    return result;
}

int linear_recurrence_nth(const vector<int>& initial,
                          const vector<int>& recurrence,
                          long long n) {
    if (n < (long long)initial.size()) return initial[n];

    int k = recurrence.size();
    if (k == 0) return 0;

    vector<int> result(k, 0), base(k, 0);
    result[0] = 1;

    if (k == 1) base[0] = recurrence[0];
    else base[1] = 1;

    while (n > 0) {
        if (n & 1) result = combine(result, base, recurrence);
        base = combine(base, base, recurrence);
        n >>= 1;
    }

    long long answer = 0;
    for (int i = 0; i < k; ++i) {
        answer += 1LL * result[i] * initial[i] % MOD;
        if (answer >= MOD) answer -= MOD;
    }
    return answer;
}

struct Edge {
    int to;
    int weight;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<string> words(n);
    for (string& word : words) cin >> word;

    vector<string> residuals;
    unordered_map<string, int> residual_index;

    for (const string& word : words) {
        for (int start = 1; start < (int)word.size(); ++start) {
            string suffix = word.substr(start);
            if (!residual_index.count(suffix)) {
                int index = residuals.size();
                residual_index[suffix] = index;
                residuals.push_back(suffix);
            }
        }
    }

    auto state_id = [&](const string& residual, int orientation) {
        return 1 + 2 * residual_index.at(residual) + orientation;
    };

    int states = 1 + 2 * (int)residuals.size();
    vector<vector<Edge>> graph(states);

    for (const string& first : words) {
        for (const string& second : words) {
            int weight = min(first.size(), second.size());

            if (first == second) {
                graph[0].push_back({0, weight});
            } else if (first.size() > second.size() &&
                       starts_with(first, second)) {
                string residual = first.substr(second.size());
                graph[0].push_back({state_id(residual, 0), weight});
            } else if (second.size() > first.size() &&
                       starts_with(second, first)) {
                string residual = second.substr(first.size());
                graph[0].push_back({state_id(residual, 1), weight});
            }
        }
    }

    for (int index = 0; index < (int)residuals.size(); ++index) {
        const string& residual = residuals[index];

        for (int orientation = 0; orientation < 2; ++orientation) {
            int from = 1 + 2 * index + orientation;

            for (const string& word : words) {
                int weight = min(residual.size(), word.size());

                if (residual == word) {
                    graph[from].push_back({0, weight});
                } else if (residual.size() > word.size() &&
                           starts_with(residual, word)) {
                    string next_residual = residual.substr(word.size());
                    graph[from].push_back({
                        state_id(next_residual, orientation), weight
                    });
                } else if (word.size() > residual.size() &&
                           starts_with(word, residual)) {
                    string next_residual = word.substr(residual.size());
                    graph[from].push_back({
                        state_id(next_residual, orientation ^ 1), weight
                    });
                }
            }
        }
    }

    int degree_bound = 5 * states;
    int terms = 2 * degree_bound + 10;

    vector<vector<int>> dp(terms, vector<int>(states, 0));
    vector<int> sequence(terms, 0);
    dp[0][0] = 1;

    for (int length = 0; length < terms; ++length) {
        sequence[length] = dp[length][0];

        for (int state = 0; state < states; ++state) {
            int current = dp[length][state];
            if (current == 0) continue;

            for (const Edge& edge : graph[state]) {
                int next_length = length + edge.weight;
                if (next_length >= terms) continue;

                int& destination = dp[next_length][edge.to];
                destination += current;
                if (destination >= MOD) destination -= MOD;
            }
        }
    }

    if (m < terms) {
        cout << sequence[m] << '\n';
        return 0;
    }

    vector<int> recurrence = berlekamp_massey(sequence);
    vector<int> initial(sequence.begin(),
                        sequence.begin() + recurrence.size());

    cout << linear_recurrence_nth(initial, recurrence, m) << '\n';
    return 0;
}

