    vector<long long> C(1, 1), B(1, 1);
    int L = 0, shift = 1;
    long long last = 1;

    for (int n = 0; n < (int)s.size(); ++n) {
        long long discrepancy = s[n];
        for (int i = 1; i <= L; ++i) {
            discrepancy = (discrepancy + C[i] * s[n - i]) % MOD;
        }

        if (discrepancy == 0) {
            ++shift;
            continue;
        }

        vector<long long> oldC = C;
        long long coef = discrepancy * mod_pow(last, MOD - 2) % MOD;

        if ((int)C.size() < (int)B.size() + shift)
            C.resize(B.size() + shift, 0);

        for (int i = 0; i < (int)B.size(); ++i) {
            C[i + shift] = (C[i + shift] - coef * B[i]) % MOD;
            if (C[i + shift] < 0) C[i + shift] += MOD;
        }

