            L = n + 1 - L;
            B = oldC;
            last = discrepancy;
            shift = 1;
        } else {
            ++shift;
        }
    }

    C.resize(L + 1);
    vector<long long> recurrence(L);
    for (int i = 1; i <= L; ++i) {
        recurrence[i - 1] = (MOD - C[i]) % MOD;
    }
    return recurrence;
}

vector<long long> combine_polynomials(
    const vector<long long>& a,
    const vector<long long>& b,
    const vector<long long>& recurrence
) {
    int L = recurrence.size();
    vector<long long> product(2 * L - 1, 0);

    for (int i = 0; i < L; ++i) {
        if (a[i] == 0) continue;
        for (int j = 0; j < L; ++j) {
            product[i + j] =
                (product[i + j] + a[i] * b[j]) % MOD;
        }
    }

    for (int degree = 2 * L - 2; degree >= L; --degree) {
        long long value = product[degree];
        if (value == 0) continue;

        for (int i = 1; i <= L; ++i) {
            product[degree - i] =
                (product[degree - i] +
                 value * recurrence[i - 1]) % MOD;
        }
    }

    product.resize(L);
    return product;
}

