    const vector<long long>& initial,
    const vector<long long>& recurrence,
    long long n
) {
    int L = recurrence.size();
    if (n < (long long)initial.size()) return initial[n];
    if (L == 0) return 0;

    vector<long long> result(L, 0), base(L, 0);
    result[0] = 1;

    if (L == 1) base[0] = recurrence[0];
    else base[1] = 1;

    while (n > 0) {
        if (n & 1)
            result = combine_polynomials(result, base, recurrence);
        base = combine_polynomials(base, base, recurrence);
        n >>= 1;
    }

    long long answer = 0;
    for (int i = 0; i < L; ++i) {
        answer = (answer + result[i] * initial[i]) % MOD;
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<string> words(n);
    for (string& word : words) cin >> word;

    set<string> suffixSet;
    for (const string& word : words) {
        for (int pos = 1; pos < (int)word.size(); ++pos) {
            suffixSet.insert(word.substr(pos));
        }
    }

    vector<string> states;
    states.push_back("");
    for (const string& suffix : suffixSet)
        states.push_back(suffix);

    int K = states.size();
    unordered_map<string, int> stateId;
    for (int i = 0; i < K; ++i)
        stateId[states[i]] = i;

    unordered_map<string, vector<long long>> memo;

    function<vector<long long>(const string&)> resolveAhead =
        [&](const string& residual) -> vector<long long> {
            auto it = memo.find(residual);
            if (it != memo.end()) return it->second;

            vector<long long> result(K, 0);

            for (const string& bword : words) {
                if (starts_with(residual, bword)) {
                    if (residual.size() == bword.size()) {
                        result[0] = (result[0] + 1) % MOD;
                    } else {
                        vector<long long> sub =
                            resolveAhead(residual.substr(bword.size()));
                        for (int i = 0; i < K; ++i)
                            result[i] = (result[i] + sub[i]) % MOD;
                    }
                } else if (starts_with(bword, residual)) {
                    string remaining = bword.substr(residual.size());
                    int destination = stateId.at(remaining);
                    result[destination] =
                        (result[destination] + 1) % MOD;
                }
            }

            memo[residual] = result;
            return result;
        };

    const int MAX_LEN = 5;
    vector<vector<vector<long long>>> transitions(
        MAX_LEN + 1,
        vector<vector<long long>>(K, vector<long long>(K, 0))
    );

    for (int source = 0; source < K; ++source) {
        const string& bResidual = states[source];

        for (const string& aword : words) {
            int length = aword.size();
            vector<long long> destinations(K, 0);

            if (source == 0) {
                destinations = resolveAhead(aword);
            } else if (starts_with(bResidual, aword)) {
                if (bResidual.size() == aword.size()) {
                    destinations[0] = 1;
                } else {
                    string remaining = bResidual.substr(aword.size());
                    destinations[stateId.at(remaining)] = 1;
                }
            } else if (starts_with(aword, bResidual)) {
                if (aword.size() == bResidual.size()) {
                    destinations[0] = 1;
                } else {
                    destinations =
                        resolveAhead(aword.substr(bResidual.size()));
                }
            }

            for (int destination = 0; destination < K; ++destination) {
                transitions[length][source][destination] =
                    (transitions[length][source][destination] +
                     destinations[destination]) % MOD;
            }
        }
    }

    int dimensionBound = K * MAX_LEN;
    int sequenceLength = 2 * dimensionBound + 10;

    vector<vector<long long>> dp(sequenceLength, vector<long long>(K, 0));
    vector<long long> sequence(sequenceLength, 0);

    dp[0][0] = 1;
    sequence[0] = 1;

    for (int t = 1; t < sequenceLength; ++t) {
        for (int length = 1; length <= MAX_LEN && length <= t; ++length) {
            for (int source = 0; source < K; ++source) {
                long long ways = dp[t - length][source];
                if (ways == 0) continue;

                for (int destination = 0; destination < K; ++destination) {
                    long long edges =
                        transitions[length][source][destination];
                    if (edges == 0) continue;

                    dp[t][destination] =
                        (dp[t][destination] + ways * edges) % MOD;
                }
            }
        }
        sequence[t] = dp[t][0];
    }

    if (m < sequenceLength) {
        cout << sequence[m] << '\n';
        return 0;
    }

    vector<long long> recurrence = berlekamp_massey(sequence);
    vector<long long> initial(
        sequence.begin(),
        sequence.begin() + recurrence.size()
    );

    cout << linear_recurrence_nth(initial, recurrence, m) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;
static const int G = 3;

int modPow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return (int)r;
}

void ntt(vector<int>& a, bool invert) {
    int n = (int)a.size();

    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        while (j & bit) {
            j ^= bit;
            bit >>= 1;
        }
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }

    for (int len = 2; len <= n; len <<= 1) {
        int wlen = modPow(G, (MOD - 1) / len);
        if (invert) wlen = modPow(wlen, MOD - 2);

        for (int i = 0; i < n; i += len) {
            long long w = 1;
            int half = len >> 1;
            for (int j = 0; j < half; ++j) {
                int u = a[i + j];
                int v = (int)(a[i + j + half] * w % MOD);

                int x = u + v;
                if (x >= MOD) x -= MOD;
                a[i + j] = x;

                x = u - v;
                if (x < 0) x += MOD;
                a[i + j + half] = x;

                w = w * wlen % MOD;
            }
        }
    }

    if (invert) {
        int invN = modPow(n, MOD - 2);
        for (int& x : a) x = (int)((long long)x * invN % MOD);
    }
}

vector<int> multiply(const vector<int>& a, const vector<int>& b) {
    if (a.empty() || b.empty()) return {};

    if (min(a.size(), b.size()) <= 32) {
        vector<int> result(a.size() + b.size() - 1, 0);
        for (int i = 0; i < (int)a.size(); ++i) {
            for (int j = 0; j < (int)b.size(); ++j) {
                result[i + j] = (result[i + j] +
                    (long long)a[i] * b[j]) % MOD;
            }
        }
        return result;
    }

    int need = (int)a.size() + (int)b.size() - 1;
    int size = 1;
    while (size < need) size <<= 1;

    vector<int> fa(a.begin(), a.end());
    vector<int> fb(b.begin(), b.end());
    fa.resize(size);
    fb.resize(size);

    ntt(fa, false);
    ntt(fb, false);
    for (int i = 0; i < size; ++i) {
        fa[i] = (int)((long long)fa[i] * fb[i] % MOD);
    }
    ntt(fa, true);
    fa.resize(need);
    return fa;
}

vector<int> berlekampMassey(const vector<int>& s) {
    vector<int> C(1, 1), B(1, 1);
    int L = 0;
    int shift = 1;
    int lastDiscrepancy = 1;

    for (int pos = 0; pos < (int)s.size(); ++pos) {
        long long discrepancy = s[pos];
        for (int i = 1; i <= L; ++i) {
            discrepancy += (long long)C[i] * s[pos - i];
            if (discrepancy >= (1LL << 62)) discrepancy %= MOD;
        }
        int d = (int)(discrepancy % MOD);

        if (d == 0) {
            ++shift;
            continue;
        }

        vector<int> oldC = C;
        int coefficient = (int)((long long)d *
                                modPow(lastDiscrepancy, MOD - 2) % MOD);

        if ((int)C.size() < (int)B.size() + shift) {
            C.resize(B.size() + shift, 0);
        }

        for (int i = 0; i < (int)B.size(); ++i) {
            C[i + shift] = (C[i + shift] -
                            (long long)coefficient * B[i]) % MOD;
            if (C[i + shift] < 0) C[i + shift] += MOD;
        }

        if (2 * L <= pos) {
            L = pos + 1 - L;
            B = move(oldC);
            lastDiscrepancy = d;
            shift = 1;
        } else {
            ++shift;
        }
    }

    C.resize(L + 1);
    return C;
}

int linearRecurrenceTerm(const vector<int>& initial,
                         const vector<int>& characteristic,
                         long long index) {
    if (index < (long long)initial.size()) return initial[index];

    int L = (int)characteristic.size() - 1;
    if (L == 0) return 0;

    vector<int> Q = characteristic;
    vector<int> P(L, 0);

    for (int k = 0; k < L; ++k) {
        long long value = 0;
        for (int i = 0; i <= k && i < (int)Q.size(); ++i) {
            value += (long long)Q[i] * initial[k - i];
            if (value >= (1LL << 62)) value %= MOD;
        }
        P[k] = (int)(value % MOD);
    }

    while (index > 0) {
        vector<int> negativeQ = Q;
        for (int i = 1; i < (int)negativeQ.size(); i += 2) {
            if (negativeQ[i] != 0) negativeQ[i] = MOD - negativeQ[i];
        }

        vector<int> productP = multiply(P, negativeQ);
        vector<int> productQ = multiply(Q, negativeQ);

        vector<int> nextP;
        vector<int> nextQ;

        int parity = index & 1;
        for (int i = parity; i < (int)productP.size(); i += 2) {
            nextP.push_back(productP[i]);
        }
        for (int i = 0; i < (int)productQ.size(); i += 2) {
            nextQ.push_back(productQ[i]);
        }

        while (nextP.size() > 1 && nextP.back() == 0) nextP.pop_back();
        while (nextQ.size() > 1 && nextQ.back() == 0) nextQ.pop_back();

        P.swap(nextP);
        Q.swap(nextQ);
        index >>= 1;
    }

    return (int)((long long)P[0] * modPow(Q[0], MOD - 2) % MOD);
}

struct TrieNode {
    array<int, 26> child;
    bool terminal = false;

    TrieNode() {
        child.fill(-1);
    }
};

struct Edge {
    int from;
    int to;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<TrieNode> trie(1);

    for (int i = 0; i < n; ++i) {
        string word;
        cin >> word;

        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (trie[node].child[c] == -1) {
                trie[node].child[c] = (int)trie.size();
                trie.emplace_back();
            }
            node = trie[node].child[c];
        }
        trie[node].terminal = true;
    }

    int trieSize = (int)trie.size();
    vector<int> activeId(trieSize, -1);
    vector<int> activeNodes;

    for (int node = 0; node < trieSize; ++node) {
        bool hasChild = false;
        for (int c = 0; c < 26; ++c) {
            if (trie[node].child[c] != -1) {
                hasChild = true;
                break;
            }
        }

        if (node == 0 || hasChild) {
            activeId[node] = (int)activeNodes.size();
            activeNodes.push_back(node);
        }
    }

    int K = (int)activeNodes.size();
    vector<array<vector<int>, 26>> transitions(K);

    for (int state = 0; state < K; ++state) {
        int node = activeNodes[state];

        for (int c = 0; c < 26; ++c) {
            int nextNode = trie[node].child[c];
            if (nextNode == -1) continue;

            if (trie[nextNode].terminal) {
                transitions[state][c].push_back(0);
            }

            if (activeId[nextNode] != -1) {
                transitions[state][c].push_back(activeId[nextNode]);
            }
        }
    }

    int states = K * K;
    vector<Edge> edges;

    for (int a = 0; a < K; ++a) {
        for (int b = 0; b < K; ++b) {
            int from = a * K + b;

            for (int c = 0; c < 26; ++c) {
                for (int nextA : transitions[a][c]) {
                    for (int nextB : transitions[b][c]) {
                        edges.push_back({from, nextA * K + nextB});
                    }
                }
            }
        }
    }

    int terms = 2 * states + 5;
    vector<int> sequence;
    sequence.reserve(terms);

    vector<int> dp(states, 0), nextDp(states, 0);
    dp[0] = 1;

    for (int length = 0; length < terms; ++length) {
        sequence.push_back(dp[0]);
        fill(nextDp.begin(), nextDp.end(), 0);

        for (const Edge& edge : edges) {
            int value = nextDp[edge.to] + dp[edge.from];
            if (value >= MOD) value -= MOD;
            nextDp[edge.to] = value;
        }

        dp.swap(nextDp);
    }

    if (m < (long long)sequence.size()) {
        cout << sequence[m] << '\n';
        return 0;
    }

    vector<int> characteristic = berlekampMassey(sequence);
    int L = (int)characteristic.size() - 1;
    vector<int> initial(sequence.begin(), sequence.begin() + L);

    cout << linearRecurrenceTerm(initial, characteristic, m) << '\n';
    return 0;
}
